const express = require('express');
const { Scalekit } = require('@scalekit-sdk/node');
const jwt = require('jsonwebtoken');

const app = express();
const port = 3001;

// Initialize Scalekit client
const scalekit = new Scalekit(
  process.env.SCALEKIT_ENV_URL || 'https://example.scalekit.com',
  process.env.SCALEKIT_CLIENT_ID || 'client_id',
  process.env.SCALEKIT_CLIENT_SECRET || 'client_secret'
);

app.get('/callback', async (req, res) => {
  const { code, state } = req.query;

  if (!code) {
    return res.status(400).json({ error: 'Authorization code is missing' });
  }

  try {
    const tokens = await scalekit.authenticateWithCode(code, 'http://localhost:3001/callback');

    // Decode the idToken
    const decodedToken = jwt.decode(tokens.idToken);

    if (!decodedToken) {
      return res.status(400).json({ error: 'Failed to decode ID token' });
    }

    const { email, name } = decodedToken;

    res.json({ email, name });
  } catch (error) {
    console.error('Error authenticating with Scalekit:', error);
    res.status(500).json({ error: 'Internal server error during authentication' });
  }
});

app.listen(port, () => {
  console.log(`Server running at http://localhost:${port}`);
});

